(function(){
  const page=document.body.dataset.page||'home';
  const lang=new URLSearchParams(location.search).get('lang')==='tt'?'tt':'ru';
  const d=GUIDE[lang], H=d.home, I=d.intro, L=d.lesson;
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const href=(file,l=lang)=>`${file}?lang=${l}`;
  const link=(file,text,cls='button')=>`<a class="${cls}" href="${href(file)}">${esc(text)}</a>`;
  const item=(x)=>`<article class="step"><div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p>${x[2]?`<p class="quote">${esc(x[2])}</p>`:''}</div></article>`;
  function head(){return `<a class="skip" href="#main">${lang==='ru'?'К содержанию':'Эчтәлеккә'}</a><header class="site-head"><div class="shell head-inner"><a class="brand" href="${href('index.html')}"><span class="brand-mark" aria-hidden="true">✦</span><span>${esc(d.name)}</span></a><nav class="head-nav" aria-label="${lang==='ru'?'Разделы пособия':'Кулланма бүлекләре'}"><a href="${href('intro.html')}" ${page==='intro'?'aria-current="page"':''}>${esc(d.nav[0])}</a><a href="${href('index.html')}#map" ${page==='home'?'aria-current="page"':''}>${esc(d.nav[1])}</a><a href="${href('lesson01.html')}" ${page==='lesson'?'aria-current="page"':''}>${esc(d.nav[2])}</a></nav><div class="langs" aria-label="Язык / Тел"><a href="${href(page==='home'?'index.html':page==='intro'?'intro.html':'lesson01.html','ru')}" ${lang==='ru'?'aria-current="true"':''}>RU</a><a href="${href(page==='home'?'index.html':page==='intro'?'intro.html':'lesson01.html','tt')}" ${lang==='tt'?'aria-current="true"':''}>ТАТ</a></div></div></header>`}
  function footer(){return `<footer class="footer"><div class="shell"><span>${esc(d.mark)} · ${lang==='ru'?'Образец: введение и занятие 1':'Үрнәк: кереш һәм 1 нче дәрес'}</span><a href="${href('index.html')}#map">${esc(d.nav[1])}</a></div></footer>`}
  function home(){let blocks=H.groups.map((g,gi)=>{let cards=d.topics.map((x,i)=>({...x,n:i+1})).filter(x=>x[2]===gi).map(x=>`<article class="chapter ${x.n===1?'current':''}"><div class="chapter-num">${String(x.n).padStart(2,'0')}</div><div><h3>${x.n===1?`<a href="${href('lesson01.html')}">${esc(x[0])}</a>`:esc(x[0])}</h3><p>${esc(H.lessons)} ${esc(x[1])} ${x.n===1?`<span class="provisional">${esc(d.preview)}</span>`:''}</p></div></article>`).join('');return `<section class="chapter-section"><h2>${esc(g)}</h2><div class="chapter-list">${cards}</div></section>`}).join('');return `<section class="hero"><div class="shell hero-grid"><div><p class="eyebrow">${esc(d.mark)}</p><h1>${esc(d.name)}</h1><p>${esc(H.hero)}</p><p>${esc(H.desc)}</p><div class="actions">${link('intro.html',H.intro)}${link('lesson01.html',H.first,'button secondary')}</div></div><div class="hero-card"><div class="seal" aria-hidden="true">۞</div><strong>20 · 50</strong><p>${esc(lang==='ru'?'20 методических занятий собирают 50 ученических уроков в понятную для преподавателя карту.':'20 методик дәрес 50 укучы дәресен укытучы өчен аңлаешлы картага җыя.')}</p></div></div></section><main id="main" class="shell main-content"><section class="intro-feature"><div><p class="kicker">${esc(H.introTitle)}</p><h2>${esc(I.title)}</h2><p>${esc(H.introDesc)}</p>${link('intro.html',H.intro,'button ghost')}</div><p class="note">${esc(H.introNote)}</p></section><section id="map"><div class="section-head"><div><p class="kicker">20 · 50</p><h2>${esc(H.mapTitle)}</h2></div><p>${esc(H.mapDesc)}</p></div>${blocks}</section><div class="section-banner"><strong>${esc(I.firstTitle)}</strong><p>${esc(I.firstDesc)}</p>${link('lesson01.html',H.first,'button ghost')}</div></main>`}
  function pageHero(eyebrow,title,lead,chips){return `<section class="page-hero"><div class="shell"><div class="crumb"><a href="${href('index.html')}">${esc(d.nav[1])}</a><span>•</span><span>${esc(eyebrow)}</span></div><p class="eyebrow">${esc(d.mark)}</p><h1>${esc(title)}</h1><p>${esc(lead)}</p><div class="reading-line">${chips.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></section>`}
  function intro(){return `${pageHero(I.eyebrow,I.title,I.lead,I.chips)}<main id="main" class="shell main-content"><section class="panel"><p class="kicker">${lang==='ru'?'Цель пособия':'Кулланманың максаты'}</p><h2>${esc(I.goalTitle)}</h2><p class="lead">${esc(I.goal)}</p></section><section class="panel"><p class="kicker">${lang==='ru'?'Основной ход':'Төп юл'}</p><h2>${lang==='ru'?'От страницы книги к пониманию':'Китап битеннән аңлауга'}</h2><div class="flow">${I.triangle.map((t,i)=>`<article><b>${esc(t)}</b><p>${esc(I.triangleText[i])}</p></article>`).join('')}</div></section><section class="panel"><h2>${esc(I.rolesTitle)}</h2><div class="steps">${I.roles.map(item).join('')}</div></section><section class="panel"><h2>${esc(I.routeTitle)}</h2><div class="steps">${I.route.map(item).join('')}</div></section><section class="panel"><p class="kicker">20 ≠ 50</p><h2>${esc(I.boundaryTitle)}</h2><p class="lead">${esc(I.boundary)}</p></section><div class="bookstrip"><div><h3>${esc(I.firstTitle)}</h3><p>${esc(I.firstDesc)}</p></div>${link('lesson01.html',H.first)}</div><div class="page-nav">${link('index.html',H.mapTitle,'button ghost')}</div></main>`}
  function lesson(){const studentUrl=(n)=>`https://sajidaturseb.github.io/fiqh-test/?lesson=${n}&lang=${lang}`;return `${pageHero(L.eyebrow,L.title,L.lead,L.chips)}<main id="main" class="shell main-content"><section class="panel"><p class="kicker">${lang==='ru'?'Проверочный вход':'Башлангыч сорау'}</p><h2>${esc(L.questionTitle)}</h2><p class="lead">${esc(L.question)}</p><details class="callout"><summary>${lang==='ru'?'Показать методический ответ':'Методик җавапны күрсәтү'}</summary><p>${esc(L.questionAnswer)}</p></details></section><section class="panel"><p class="kicker">${lang==='ru'?'Главная схема':'Төп схема'}</p><h2>${esc(L.schemeTitle)}</h2><p>${esc(L.schemeLead)}</p><div class="two-path">${L.paths.map(x=>`<article class="path"><span class="path-no">${esc(x[0].split(' · ')[0])}</span><h3>${esc(x[0].split(' · ')[1])}</h3><p>${esc(x[1])}</p><p class="example">${esc(x[2])}</p></article>`).join('')}</div><p class="bridge">${esc(L.bridge)}</p></section><section class="panel"><p class="kicker">${lang==='ru'?'Сценарий объяснения':'Аңлату барышы'}</p><h2>${esc(L.stepsTitle)}</h2><div class="steps">${L.steps.map(item).join('')}</div></section><section class="panel"><p class="kicker">${lang==='ru'?'Схема на доске':'Тактадагы схема'}</p><h2>${esc(L.waterTitle)}</h2><p>${esc(L.waterLead)}</p><div class="flow">${L.water.map(x=>`<article><b>${esc(x[0])}</b><p>${esc(x[1])}</p></article>`).join('')}</div></section><section class="panel"><p class="kicker">${lang==='ru'?'Ученики выбирают правило':'Укучылар кагыйдә сайлый'}</p><h2>${esc(L.casesTitle)}</h2><div class="case-grid">${L.cases.map((x,i)=>`<article class="case"><span class="tag">${lang==='ru'?'Ситуация':'Хәл'} ${i+1}</span><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p><details><summary>${lang==='ru'?'Разбор для учителя':'Укытучы өчен аңлатма'}</summary><p>${esc(x[2])}</p></details></article>`).join('')}</div></section><section class="panel"><h2>${esc(L.timingTitle)}</h2><div class="timing">${L.timing.map(x=>`<div><strong>${esc(x[0])}</strong>${esc(x[1])}</div>`).join('')}</div></section><section class="panel"><h2>${esc(L.mistakesTitle)}</h2><div class="mistake-list">${L.mistakes.map(x=>`<article class="mistake"><b>${esc(x[0])}</b><p>${esc(x[1])}</p></article>`).join('')}</div></section><section class="panel"><h2>${esc(L.checkTitle)}</h2><ul class="check-list">${L.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><div class="bookstrip"><div><h3>${esc(L.bookTitle)}</h3><p>${esc(L.book)}</p><p><a href="${studentUrl(1)}" target="_blank" rel="noopener">${esc(lang==='ru'?'Урок 1 курса':'Курсның 1 нче дәресе')}</a> · <a href="${studentUrl(2)}" target="_blank" rel="noopener">${esc(lang==='ru'?'Урок 2 курса':'Курсның 2 нче дәресе')}</a></p></div></div><div class="page-nav">${link('index.html',L.back,'button ghost')}${link('intro.html',L.intro,'button ghost')}</div></main>`}
  document.documentElement.lang=lang;
  document.title=(page==='lesson'?L.title:page==='intro'?I.title:d.name)+' · '+d.mark;
  document.getElementById('app').innerHTML=head()+(page==='lesson'?lesson():page==='intro'?intro():home())+footer();
})();
